mapper.select:


    SELECT w.*,(SELECT COUNT(*) FROM favorite_word_context x WHERE x.favorite_word_id=w.id) AS context_count
    FROM user_favorite_word w

  SELECT  

WHERE w.user_id=#{user}

  AND (w.lemma LIKE #{pattern} ESCAPE '!' OR

    EXISTS(SELECT 1 FROM favorite_word_context x WHERE x.favorite_word_id=w.id AND x.sentence_snapshot LIKE #{pattern} ESCAPE '!')
    c.sentence_snapshot LIKE #{pattern} ESCAPE '!'
  )



    AND EXISTS(SELECT 1 FROM favorite_word_context x WHERE x.favorite_word_id=w.id AND x.origin_key=#{origin})
    AND c.origin_key=#{origin}





      AND (w.created_at <> #{afterAt}
      OR (w.created_at=#{afterAt} AND w.id <> #{afterId}))


      AND (c.created_at <> #{afterAt}
      OR (c.created_at=#{afterAt} AND c.id <> #{afterId}))



ORDER BY 
  w.created_at DESC,w.id DESC
  c.created_at DESC,c.id DESC
 LIMIT #{limit}
